@Test
public void testEJB() throws Exception {
    Properties p = new Properties();
    p.put("java.naming.factory.initial", "org.apache.openejb.client.RemoteInitialContextFactory");
    p.put("java.naming.provider.url", "127.0.0.1:4201");
    InitialContext ctx = new InitialContext(p);
    Object obj = ctx.lookup("/Stax");
    StaxHome ejbHome = (StaxHome) PortableRemoteObject.narrow(obj, StaxHome.class);
    StaxObject ejbObject = ejbHome.create();
    List factoryList = ejbObject.testStax();
    assertEquals(3, factoryList.size());
    assertEquals("InputFactory", "com.ctc.wstx.stax.WstxInputFactory", factoryList.get(0));
    assertEquals("OutputFactory", "com.ctc.wstx.stax.WstxOutputFactory", factoryList.get(1));
    assertEquals("EventFactory", "com.ctc.wstx.stax.WstxEventFactory", factoryList.get(2));
    System.out.println(factoryList);
}

